const bruto = $('Extrai cardápio').first().json ?? {};
let menu = bruto.output ?? bruto;
if (Array.isArray(menu)) menu = menu[0]?.output ?? menu[0] ?? {};
if (menu?.output) menu = menu.output;
menu = menu ?? {};

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

// Unifica Proteínas e Misturas: são nomes alternativos da mesma categoria.
const proteinas = [
  ...(Array.isArray(menu.proteinas) ? menu.proteinas : []),
  ...(Array.isArray(menu.misturas) ? menu.misturas : []),
].map((item) => String(item ?? '').trim()).filter(Boolean);

if (proteinas.length === 0) {
  throw new Error(
    'Nenhuma opção principal foi identificada. Verifique a mensagem enviada e a extração do Gemini.'
  );
}

// Embute os dados extraídos no HTML real (escapa < para evitar fechamento do script).
const dadosParaHtml = JSON.stringify({
  proteinas,
  acompanhamentos: Array.isArray(menu.acompanhamentos) ? menu.acompanhamentos : [],
  data: menu.data ?? '',
  estabelecimento: menu.estabelecimento ?? '',
  titulo: menu.titulo ?? '',
}).replace(/</g, '\\u003c');

// Monta os cartões das proteínas
const categoriasHtml = `
  <div class="categoria">
    <div class="itens">
      ${proteinas.map((proteina) => `
        <div class="item">
          <div class="item-nome">${esc(proteina)}</div>
        </div>
      `).join('')}
    </div>
  </div>
`;

const data = String(menu.data ?? '').trim()
  ? esc(menu.data)
  : new Date().toLocaleDateString('pt-BR', {
      timeZone: 'America/Fortaleza',
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    });

const restaurante = esc(menu.estabelecimento || 'Restaurante');

const titulo = esc(menu.titulo || 'Cardápio de Hoje');

// HTML completo do cardápio
const template = `
