  Campos vazios usam valores padrão para data, estabelecimento e título. Proteínas, misturas e acompanhamentos são extraídos dinamicamente.
-->
<script id="dados" type="application/json">
${dadosParaHtml}
</script>

<div class="pagina" id="pagina">
  <div class="xadrez topo"></div>

  <div class="conteudo" id="conteudo">

    <header>
      <svg class="panela" viewBox="0 0 160 130" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
