<script>
(function(){
  var DEFAULTS={estabelecimento:'Marmitaria da Tia Cláudia',titulo:'Cardápio do Dia'};
  var raw; try{raw=JSON.parse(document.getElementById('dados').textContent)}catch(e){raw=null}
  var d=raw; if(Array.isArray(d))d=d[0]; if(d&&d.output)d=d.output; d=d||{};
  function list(v){return Array.isArray(v)?v.map(function(x){return String(x==null?'':x).trim()}).filter(Boolean):[]}
  function cap(v){return v.charAt(0).toUpperCase()+v.slice(1)}
  // Backward compatibility: old workflow may still send both fields; combine into one list.
  var main=list(d.proteinas).concat(list(d.misturas));
  var sides=list(d.acompanhamentos);
  document.getElementById('estabelecimento').textContent=(d.estabelecimento||'').trim()||DEFAULTS.estabelecimento;
  document.getElementById('titulo').textContent=(d.titulo||'').trim()||DEFAULTS.titulo;
  var date=(d.data||'').trim(); if(!date){try{date=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Sao_Paulo'})}catch(e){date=new Date().toLocaleDateString('pt-BR')}}
  document.getElementById('data').textContent=date;
  var mainBox=document.getElementById('proteinas');
  if(!main.length){var empty=document.createElement('div');empty.className='proteina';empty.textContent='Cardápio em breve';mainBox.appendChild(empty)}
  main.forEach(function(n){var card=document.createElement('div');card.className='proteina';var dot=document.createElement('span');dot.className='ponto';var label=document.createElement('span');label.textContent=cap(n);card.appendChild(dot);card.appendChild(label);mainBox.appendChild(card)});
  var sideBox=document.getElementById('acompanhamentos');
