  // Fit content without clipping: progressively tighten all scaled typography and spacing.
  var content=document.getElementById('conteudo'); var scale=1;
  while(content.scrollHeight>content.clientHeight+2&&scale>0.48){scale=Math.round((scale-0.04)*100)/100;document.documentElement.style.setProperty('--fit',scale)}
})();
